package com.example.kyrgyzkeyboard

import android.app.Application
import android.content.Context
import android.content.SharedPreferences
import com.example.kyrgyzkeyboard.data.local.DictionaryDao
import com.example.kyrgyzkeyboard.data.local.DictionaryDatabase
import com.example.kyrgyzkeyboard.data.repository.DictionaryRepository
import com.example.kyrgyzkeyboard.data.repository.SettingsRepository
import com.example.kyrgyzkeyboard.ui.settings.SettingsPreferences
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.android.HiltAndroidApp
import dagger.hilt.android.qualifiers.ApplicationContext
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@HiltAndroidApp
class KeyboardApp : Application()

/**
 * 应用级 DI Module：数据库 / DAO / Repositories / DataStore 封装。
 */
@Module
@InstallIn(SingletonComponent::class)
object AppModule {

    @Provides
    @Singleton
    fun provideDatabase(@ApplicationContext context: Context): DictionaryDatabase =
        DictionaryDatabase.getInstance(context)

    @Provides
    fun provideDictionaryDao(db: DictionaryDatabase): DictionaryDao = db.wordDao()

    @Provides
    @Singleton
    fun provideDictionaryRepository(dao: DictionaryDao): DictionaryRepository =
        DictionaryRepository(dao)

    @Provides
    @Singleton
    fun provideSharedPreferences(@ApplicationContext context: Context): SharedPreferences =
        context.getSharedPreferences(SettingsRepository.PREFS_NAME, Context.MODE_PRIVATE)

    @Provides
    @Singleton
    fun provideSettingsRepository(prefs: SharedPreferences): SettingsRepository =
        SettingsRepository(prefs)

    @Provides
    @Singleton
    fun provideSettingsPreferences(@ApplicationContext context: Context): SettingsPreferences =
        SettingsPreferences(context)
}